def solve(weights, values, capacity):
    # 0/1 knapsack DP: dp[c] = max value for capacity c
    n = len(weights)
    dp = [0] * (capacity + 1)
    for i in range(n):
        w = weights[i]
        v = values[i]
        # iterate backwards to avoid reuse
        for c in range(capacity, w - 1, -1):
            new_val = dp[c - w] + v
            if new_val > dp[c]:
                dp[c] = new_val
    return dp[capacity]

def solve(s: str) -> int:
    """Return length of longest substring without repeating characters.
    Uses sliding window with dictionary of last seen positions.
    """
    last_index = {}
    max_len = 0
    start = 0
    for i, ch in enumerate(s):
        if ch in last_index and last_index[ch] >= start:
            start = last_index[ch] + 1
        last_index[ch] = i
        max_len = max(max_len, i - start + 1)
    return max_len

