def solve(s: str) -> int:
    """Convert a valid Roman numeral string to an integer.
    Supports standard symbols I, V, X, L, C, D, M with subtractive notation.
    Returns 0 for empty string.
    """
    if not s:
        return 0
    # Mapping of symbols to values
    values = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    total = 0
    prev = 0
    # Process from right to left for subtractive handling
    for ch in reversed(s):
        val = values[ch]
        if val < prev:
            total -= val
        else:
            total += val
        prev = val
    return total

