def solve(n, edges):
    import heapq
    if n <= 0:
        return -1
    if n == 1:
        return 0
    adj = [[] for _ in range(n)]
    for edge in edges:
        if len(edge) != 3:
            continue
        a,b,w = edge
        if not (isinstance(a,int) and isinstance(b,int)):
            continue
        if not (isinstance(w,int) or isinstance(w,float)):
            continue
        if a<0 or a>=n or b<0 or b>=n:
            continue
        if w < 0:  # allow zero weight
            continue
        adj[a].append((b,w))
        adj[b].append((a,w))
    INF = 10**18
    dist = [INF]*n
    dist[0]=0
    heap=[(0,0)]
    while heap:
        d,u = heapq.heappop(heap)
        if d!=dist[u]:
            continue
        if u==n-1:
            break
        for v,w in adj[u]:
            nd = d + w
            if nd < dist[v]:
                dist[v]=nd
                heapq.heappush(heap,(nd,v))
    return dist[n-1] if dist[n-1]!=INF else -1

