def solve(n, edges):
    import heapq
    if n <= 1:
        return 0
    adj = [[] for _ in range(n)]
    for a, b, w in edges:
        if 0 <= a < n and 0 <= b < n and w >= 0:
            adj[a].append((b, w))
            adj[b].append((a, w))
    dist = [float('inf')] * n
    dist[0] = 0
    heap = [(0, 0)]
    while heap:
        d, u = heapq.heappop(heap)
        if d != dist[u]:
            continue
        if u == n - 1:
            return d
        for v, w in adj[u]:
            nd = d + w
            if nd < dist[v]:
                dist[v] = nd
                heapq.heappush(heap, (nd, v))
    return -1 if dist[n - 1] == float('inf') else dist[n - 1]
